def check_good_triples():
    good_triples = []

    # Check x = 1, 2, 3, 4
    for x in range(1, 5):
        for y in range(1, 100):
            for z in range(1, 100):
                # Calculate the numerator: (x+1)^y
                try:
                    numerator = (x + 1)**y
                except OverflowError:
                    # Should not happen in standard Python integers, but good practice.
                    continue

                # Calculate the denominator: x^z + 1
                denominator = x**z + 1

                # Check if the numerator is divisible by the denominator
                if denominator == 0:
                    # Should not happen since x>=1 and z>=1
                    continue

                if numerator % denominator == 0:
                    good_triples.append((x, y, z))

    return good_triples

